{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds beverage or food for consumption",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "cup",
          "plate",
          "saucer",
          "drinkware",
          "snack plate"
        ],
        "required_properties": [
          "holds liquid",
          "holds solid food",
          "stable base"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television or media system",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "remote",
          "controller",
          "clicker"
        ],
        "required_properties": [
          "small handheld size",
          "buttons or touch interface",
          "wireless"
        ]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Supports objects for viewing and access",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "floor",
          "console",
          "side table"
        ],
        "required_properties": [
          "flat",
          "horizontal",
          "stable",
          "within reach"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_on_surface",
        "relation": "placed_on",
        "participant_roles": [
          "refreshment_setting",
          "surface"
        ],
        "required": true
      },
      {
        "id": "control_on_surface",
        "relation": "placed_on",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshments",
        "operation": "place",
        "participant_roles": [
          "refreshment_setting",
          "surface"
        ],
        "operation_count": 2
      },
      {
        "id": "place_control",
        "operation": "place",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "Cup and plate on coffee table",
          "visual_description": "Red cup and white plate sitting on the center green coffee table."
        },
        {
          "label": "Cup and plate on desk",
          "visual_description": "Red cup and white plate sitting on the wooden desk near the bottom right."
        }
      ],
      "entertainment_control": [
        {
          "label": "Remote on desk",
          "visual_description": "Black remote control lying on the wooden desk next to the cup and plate."
        }
      ],
      "surface": [
        {
          "label": "Coffee table",
          "visual_description": "Green rectangular table in the center of the seating area."
        },
        {
          "label": "Desk",
          "visual_description": "Large wooden table on the right side of the room."
        },
        {
          "label": "Side tables",
          "visual_description": "Two small wooden tables flanking the armchairs."
        },
        {
          "label": "Rug/Floor",
          "visual_description": "Large light-colored rug covering the center of the room."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "console_under_tv",
        "label": "Console/Stand under TV",
        "visual_description": "Long wooden bench-like structure beneath the wall-mounted TV.",
        "reason": "Could contain spare remotes, drinks, or other refreshment items hidden inside."
      },
      {
        "id": "desk_drawers",
        "label": "Desk Storage",
        "visual_description": "Wooden desk with potential drawers or shelves underneath.",
        "reason": "Could contain additional remotes or refreshment supplies."
      },
      {
        "id": "side_table_shelves",
        "label": "Side Table Shelves",
        "visual_description": "Open shelving underneath the side tables next to the chairs.",
        "reason": "Could contain spare cups, plates, or other items."
      }
    ],
    "inspection_order": [
      "console_under_tv",
      "desk_drawers",
      "side_table_shelves"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
